def parse_grid(s, header):
 m=re.search(re.escape(header)+r" \((\d+)x(\d+)\):\n",s); 
 if not m:return None
 h,w=map(int,m.groups()); tail=s[m.end():]; lines=tail.splitlines()[:h]; g=[list(map(int,x.split())) for x in lines];
 assert len(g)==h and all(len(r)==w for r in g),(header,h,w,[len(r) for r in g]); return g
pairs={}
for m in users:
 s=m["content"] or ""
 for i in range(1,9):
  a=parse_grid(s,f"Demo pair {i} input"); b=parse_grid(s,f"Demo pair {i} output")
  if a and b: pairs[i]=(a,b)
print("PAIR_SUMMARY",len(pairs))
for i,(a,b) in pairs.items():
